CREATE TABLE IF NOT EXISTS cloud_snapshots(id TEXT PRIMARY KEY,kind TEXT NOT NULL,manifest_key TEXT NOT NULL,created TEXT NOT NULL,label TEXT NOT NULL DEFAULT '',deleted TEXT,expires TEXT,summary TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS cloud_history_deleted(id TEXT PRIMARY KEY,path TEXT NOT NULL,record TEXT NOT NULL,deleted TEXT NOT NULL,expires TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS cloud_history_expiry ON cloud_history_deleted(expires);
CREATE TABLE IF NOT EXISTS cloud_storage_lock(id INTEGER PRIMARY KEY CHECK(id=1),owner TEXT NOT NULL,expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cloud_object_pins(key TEXT PRIMARY KEY,expires TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS cloud_storage_pin_guard BEFORE INSERT ON cloud_object_pins WHEN EXISTS(SELECT 1 FROM cloud_storage_lock WHERE id=1 AND expires>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'private storage maintenance in progress'); END;
CREATE TRIGGER IF NOT EXISTS cloud_storage_repin_guard BEFORE UPDATE ON cloud_object_pins WHEN EXISTS(SELECT 1 FROM cloud_storage_lock WHERE id=1 AND expires>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'private storage maintenance in progress'); END;
CREATE TABLE IF NOT EXISTS cloud_gc_cursor(id INTEGER PRIMARY KEY CHECK(id=1),cursor TEXT NOT NULL);
INSERT OR IGNORE INTO cloud_gc_cursor VALUES(1,'');
CREATE TABLE IF NOT EXISTS cloud_gc_schedule(id INTEGER PRIMARY KEY CHECK(id=1),next TEXT NOT NULL);
INSERT OR IGNORE INTO cloud_gc_schedule VALUES(1,'9999-01-01T00:00:00.000Z');
CREATE TABLE IF NOT EXISTS cloud_manifest_roots(key TEXT PRIMARY KEY,objects TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cloud_storage_policy(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL);
INSERT OR IGNORE INTO cloud_storage_policy VALUES(1,'{"automatic":true,"keepReleases":3,"cacheBytes":134217728,"cacheDays":7,"recoveryDays":7}');
CREATE TABLE IF NOT EXISTS cloud_media_uploads(id TEXT PRIMARY KEY,actor TEXT NOT NULL,source_id TEXT NOT NULL,name TEXT NOT NULL,metadata TEXT NOT NULL,created TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'uploading');
ALTER TABLE cloud_media_uploads ADD COLUMN updated TEXT;
ALTER TABLE cloud_migrations ADD COLUMN touched TEXT;
ALTER TABLE cloud_transfers ADD COLUMN unindexed INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS cloud_artifacts(job_id TEXT PRIMARY KEY,manifest_key TEXT NOT NULL,created TEXT NOT NULL,files INTEGER NOT NULL,bytes INTEGER NOT NULL,expired TEXT);
CREATE TABLE IF NOT EXISTS cloud_history_groups(id TEXT PRIMARY KEY,items TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cloud_operations(id TEXT PRIMARY KEY,actor TEXT NOT NULL,version INTEGER NOT NULL,manifest_key TEXT NOT NULL,created TEXT NOT NULL,expires TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'staging');
CREATE TABLE IF NOT EXISTS cloud_exports(id TEXT PRIMARY KEY,actor TEXT NOT NULL,manifest_key TEXT NOT NULL,created TEXT NOT NULL,expires TEXT NOT NULL);
DROP TRIGGER IF EXISTS cloud_job_capture;
CREATE TRIGGER cloud_job_capture BEFORE INSERT ON cloud_jobs WHEN NEW.actor NOT IN ('github','approved-retry') AND NEW.version!=(SELECT version FROM cloud_workspace WHERE id=1) BEGIN SELECT RAISE(ABORT,'notebook changed before job capture'); END;
CREATE TRIGGER IF NOT EXISTS cloud_job_index_owner BEFORE INSERT ON cloud_job_files WHEN NOT EXISTS(SELECT 1 FROM cloud_jobs WHERE id=NEW.job_id) BEGIN SELECT RAISE(ABORT,'captured job is unavailable'); END;
CREATE TRIGGER IF NOT EXISTS cloud_workspace_version_guard BEFORE INSERT ON cloud_commits WHEN NEW.parent!=(SELECT version FROM cloud_workspace WHERE id=1) BEGIN SELECT RAISE(ABORT,'workspace version conflict'); END;
CREATE TRIGGER IF NOT EXISTS cloud_storage_commit_guard BEFORE INSERT ON cloud_commits WHEN EXISTS(SELECT 1 FROM cloud_storage_lock WHERE id=1 AND expires>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'private storage maintenance in progress'); END;
